root = os.path.expanduser(sys.argv[1] if len(sys.argv) > 1 else '~/baja-apps')
p = os.path.join(root, 'baja', 'manchester', 'menu', 'menu-factory.js')
if not os.path.isfile(p):
    sys.exit('Not found: ' + p)
s = open(p, encoding='utf-8').read()
done = 'Predict effect of removing' in s
chosen = None
if not done:
    for name, H in (('BajaSplice update', FROM_BAJASPLICE), ('Remove-exon update', FROM_REMOVE_ORF)):
        if all(s.count(old) == 1 for old, new in H):
            chosen = (name, H); break
    if not chosen:
        sys.exit('Your copy of menu-factory.js matches neither expected version (is the BajaSplice Exon-menu '
                 'update installed?). Nothing was changed.')
for rel, text in MODULES.items():
    m = os.path.join(root, rel)
    os.makedirs(os.path.dirname(m), exist_ok=True)
    open(m, 'w', encoding='utf-8').write(text)
    print('Wrote', m)
if done:
    print('Already installed:', p)
else:
    shutil.copyfile(p, p + '.before-exon-predict')
    for old, new in chosen[1]:
        s = s.replace(old, new, 1)
    open(p, 'w', encoding='utf-8').write(s)
    print('Updated', p, '(from the ' + chosen[0] + ')')
print('Restart baja-server (it caches scripts), then hard-refresh the editor (Ctrl+Shift+R).')
